        uint256 _localDisputeID,
        uint256 _localRoundID,
        uint256[] calldata _voteIDs,
        uint256 _choice,
        string memory _justification,
        uint256 _salt
    ) internal view {
        bytes32 actualVoteHash = hashVote(_choice, _salt);
        for (uint256 i = 0; i < _voteIDs.length; i++) {
            require(
